import { expect, expectStatus, test } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test(
    "uploading a document to a vendor under review is rejected with vendor_locked",
    { tag: "@DOC-06" },
    async ({ apiAs }) => {
      // Arrange: a draft vendor with a unique name, moved to "in_review" through the API.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `Doc Lock Vendor ${suffix}`,
            category: "software",
            contact_email: `doc-lock-${suffix}@vendor.test`,
          },
        }),
        201,
      );

      await expectStatus(await member.post(`/api/vendors/${created.id}/submit`), 200);

      const underReview = await expectStatus<{ status: string }>(
        await member.get(`/api/vendors/${created.id}`),
        200,
      );
      expect(underReview.status).toBe("in_review");

      // Act: upload a W-9 to the vendor under review.
      const upload = await member.post(`/api/vendors/${created.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(`W-9 for ${suffix}\n`),
          },
        },
      });

      // Assert: the scenario specifies 409 with error code vendor_locked.
      // Note: the dev note in the scenario asks to remove ensure_editable(vendor) from the
      // backend before writing this test. That is a backend change outside this test file,
      // so it is not applied here. The assertion below matches the scenario as written.
      const body = await expectStatus<{ error: { code: string } }>(upload, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
